entries[84406] = { ["name"] = "Authentic Jr. Engineer Goggles", ["text"] = "2 sec cast\nTools: Gyromatic Micro-Adjustor\nReagents:\nObsidium Bar (8), Hessonite (2), Savage Leather (2)\nProfession Trainer:\nCataclysm Engineering (1)\nCost:\n10\n\nCosmetic\nBinds when equipped\nHead Cosmetic\nDurability 40 / 40\nEquip: Makes you appear more gifted and attractive.\nUse: Add this appearance to your Warband collection." }
entries[84408] = { ["name"] = "R19 Threatfinder", ["text"] = "2 sec cast\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nObsidium Bar (6), Handful of Obsidium Bolts (6), Alicite (2)\nProfession Trainer:\nCataclysm Engineering (1)\nCost:\n10\n\nR19 Threatfinder\nUse: Attaches a permanent scope to a bow or gun that increases ranged hit by 17.\n\nAttaching this scope to a ranged weapon causes it to become soulbound. Cannot be applied to items higher than level 320.\n30" }
entries[84409] = { ["name"] = "Volatile Seaforium Blastpack", ["text"] = "2 sec cast\nTools: Gyromatic Micro-Adjustor\nReagents:\nHandful of Obsidium Bolts , Electrified Ether (2)\nProfession Trainer:\nCataclysm Engineering (5)\nCost:\n15\n\nUse: Blasts open locked doors and chests that require lockpicking skill of 35 and below.\nRequires Cataclysm Engineering\n(1)" }
entries[84410] = { ["name"] = "Safety Catch Removal Kit", ["text"] = "2 sec cast\nTools: Gyromatic Micro-Adjustor\nReagents:\nObsidium Bar (10), Handful of Obsidium Bolts (10)\nProfession Trainer:\nCataclysm Engineering (1)\nCost:\n10\n\nSafety Catch Removal Kit\nUse: Removes the safety mechanism from a bow or gun, increasing its ranged haste by 17.\n\nUsing this kit causes the bow or gun to become soulbound. Cannot be applied to items higher than level 320.\n30" }
entries[84411] = { ["name"] = "High-Powered Bolt Gun", ["text"] = "3 sec cast\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nObsidium Bar (10), Handful of Obsidium Bolts (8), Electrified Ether (4)\nProfession Trainer:\nCataclysm Engineering (15)\nCost:\n50\n\nHigh-Powered Bolt Gun\nBinds when used\nUse: Fires several charged bolts at an enemy for 108 damage and briefly interrupts casting. Consumes a Handful of Obsidium Bolts each time it's fired. (2 Min Cooldown)\n29\nRequires Cataclysm Engineering\n(1)\n\"Nearly as complicated to operate as it is to make.\"" }
entries[84412] = { ["name"] = "Personal World Destroyer", ["text"] = "3.5 sec cast\nTools: High-Powered Bolt Gun , Blacksmith Hammer\nReagents:\nObsidium Bar (10), Handful of Obsidium Bolts (8), Electrified Ether (8)\nProfession Trainer:\nCataclysm Engineering (25)\nCost:\n1\n\nPersonal World Destroyer\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your Personal World Destroyer.\n1 to 80 ( 80)" }
entries[84413] = { ["name"] = "De-Weaponized Mechanical Companion", ["text"] = "3.5 sec cast\nTools: High-Powered Bolt Gun , Arclight Spanner\nReagents:\nObsidium Bar (12), Handful of Obsidium Bolts (4), Electrified Ether (8), Jasper (2)\nProfession Trainer:\nCataclysm Engineering (25)\nCost:\n1\n\nDe-Weaponized Mechanical Companion\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your De-Weaponized Mechanical Companion.\n1 to 80 ( 80)" }
entries[84415] = { ["name"] = "Lure Master Tackle Box", ["text"] = "3.5 sec cast\nTools: Blacksmith Hammer , High-Powered Bolt Gun\nReagents:\nElementium Bar (20), Handful of Obsidium Bolts (4)\nProfession Trainer:\nCataclysm Engineering (25)\nCost:\n1\n\nLure Master Tackle Box\nBinds when equipped\n36 Slot Tackle Box" }
entries[84416] = { ["name"] = "Elementium Toolbox", ["text"] = "3.5 sec cast\nTools: Blacksmith Hammer\nReagents:\nElementium Bar (15), Volatile Earth (12)\nProfession Trainer:\nCataclysm Engineering (25)\nCost:\n1\n\nElementium Toolbox\nBinds when equipped\n36 Slot Engineering Bag\n\"Possibly the finest toolbox ever made, embellished with gold inlay.\"" }
entries[84417] = { ["name"] = "Volatile Thunderstick", ["text"] = "3 sec cast\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nElectrified Ether (2), Hardened Elementium Bar (5), Volatile Fire (6)\nOptional Reagents:\nOptional Reagent Slot (#47)\nProfession Trainer:\nCataclysm Engineering (45)\nCost:\n1\n75\n\nVolatile Thunderstick\nBinds when equipped\nRanged Gun\n6 - 12 Damage Speed 3.00\n(3.0 damage per second)\n+4 Agility\n+6 Stamina\n+ 4 Critical Strike\n+ 4 Mastery\nDurability 80 / 80\n31" }
entries[84418] = { ["name"] = "Elementium Dragonling", ["text"] = "3 sec cast\nTools: Blacksmith Hammer , High-Powered Bolt Gun\nReagents:\nHandful of Obsidium Bolts (2), Electrified Ether (8), Elementium Bar (16), Embersilk Cloth (20)\nOptional Reagents:\nOptional Reagent Slot (#47)\nProfession Trainer:\nCataclysm Engineering (25)\nCost:\n1\n\nElementium Dragonling\nBinds when equipped\nUnique-EquippedTrinket\n+ 6 Mastery\nUse: Activates your Elementium Dragonling to fight for you for 1 min. (5 Min Cooldown)\n30\nRequires Cataclysm Engineering\n(25)" }
