entries[84420] = { ["name"] = "Finely-Tuned Throat Needler", ["text"] = "3 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nObsidium Bar (4), Electrified Ether (2), Hardened Elementium Bar (5)\nOptional Reagents:\nOptional Reagent Slot (#47)\nProfession Trainer:\nCataclysm Engineering (40)\nCost:\n1\n50\n\nFinely-Tuned Throat Needler\nBinds when equipped\nRanged Crossbow\n7 - 11 Damage Speed 3.00\n(3.0 damage per second)\n+4 Agility\n+6 Stamina\n+ 4 Critical Strike\n+ 4 Haste\nDurability 80 / 80\n31" }
entries[84421] = { ["name"] = "Loot-a-Rang", ["text"] = "2 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nHardened Elementium Bar (5), Electrified Ether (5)\nProfession Trainer:\nCataclysm Engineering (40)\nCost:\n1\n50\n\nLoot-A-Rang\nBinds when used\nToy\nUse: Retrieves the loot from a nearby corpse. (3 Sec Cooldown)\nRequires Cataclysm Engineering\n(70)" }
entries[84424] = { ["name"] = "Invisibility Field", ["text"] = "2 sec cast\nRequires Belt\nTools: Arclight Spanner\nReagents:\nTinker's Kit\nPermanently attaches thousands of tiny mirrors to your belt, allowing you to attempt to turn invisible while out of combat. (3 Min Cooldown)\nProfession:\nCataclysm Engineering (1)\nDiscovery:\nCataclysm Engineering Recipes" }
entries[84425] = { ["name"] = "Cardboard Assassin", ["text"] = "2 sec cast\nRequires Belt\nTools: Arclight Spanner\nReagents:\nTinker's Kit\nPermanently attaches a tiny device to your belt, allowing you to create a Cardboard Assassin that enemies will attack. (5 Min Cooldown)\nProfession:\nCataclysm Engineering (1)\nDiscovery:\nCataclysm Engineering Recipes" }
