entries[84427] = { ["name"] = "Grounded Plasma Shield", ["text"] = "2 sec cast\nRequires Belt\nTools: Arclight Spanner\nReagents:\nTinker's Kit\nPermanently attaches grounded plasma generators to your belt, allowing you to activate a powerful shield that absorbs damage. (5 Min Cooldown)\nProfession:\nCataclysm Engineering (1)\nDiscovery:\nCataclysm Engineering Recipes" }
entries[84428] = { ["name"] = "Gnomish X-Ray Scope", ["text"] = "2 sec cast\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nHardened Elementium Bar (2), Dream Emerald (2)\nProfession Trainer:\nCataclysm Engineering (65)\nCost:\n2\n75\n\nGnomish X-Ray Scope\nUse: Attaches a permanent scope to a bow or gun that sometimes increases ranged attack power by 76 for 10 sec when dealing damage with ranged attacks.\n\nAttaching this scope to a ranged weapon causes it to become soulbound. Cannot be applied to items higher than level 320.\n30" }
entries[84429] = { ["name"] = "Goblin Barbecue", ["text"] = "2 sec cast\nTools: High-Powered Bolt Gun , Arclight Spanner\nReagents:\nElementium Bar (2), Toughened Flesh (2), Lavascale Fillet (2)\nProfession Trainer:\nCataclysm Engineering (55)\nCost:\n2\n25\n\nUse: Set out the barbecue to feed your entire raid or party!\n\nRestores 6510 health and ( 1118 / 5 * 30) mana over 30 sec. If you spend at least 10 seconds eating you will become well fed and gain 9 Stamina and 9 in another useful stat for 1 hour.\n30\nRequires Cataclysm Cooking\n(25)" }
entries[84430] = { ["name"] = "Heat-Treated Spinning Lure", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Obsidium Bolts , Elementium Bar (4), Volatile Fire\nProfession Trainer:\nCataclysm Engineering (60)\nCost:\n2\n50\n\n(2)\nUse: When applied to your fishing pole, increases Fishing by 10 for 15 minutes.\nRequires Cataclysm Fishing\n(1)\n\"Even works in lava!\"" }
